import subprocess

def count_lines(path):
    """Returns the number of lines in the text file at path by running the system's wc -l command."""
    try:
        result = subprocess.run(['wc', '-l', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if result.returncode == 0:
            # Extract the line count from the output (it's the first part of the output)
            line_count = int(result.stdout.split()[0])
            return line_count
        else:
            # If wc -l fails, raise an exception with the error message
            raise RuntimeError(f"Error running wc -l: {result.stderr}")
    except FileNotFoundError:
        raise FileNotFoundError(f"The command 'wc' is not available. Make sure it's installed and in your PATH.")
    except Exception as e:
        raise Exception(f"An error occurred: {str(e)}")
