import os
import json

def save_session(session, path):
    """
    Writes the session dictionary to a file at the specified path.

    Args:
        session (dict): A dictionary containing session data (strings, numbers, booleans, lists, nested dicts).
        path (str): The file path where the session data should be saved.
    """
    # Ensure the directory exists
    directory = os.path.dirname(path)
    if directory and not os.path.exists(directory):
        os.makedirs(directory)

    # Serialize the session data to JSON and write to file
    with open(path, 'w', encoding='utf-8') as file:
        json.dump(session, file, indent=2, ensure_ascii=False)

def load_session(path):
    """
    Reads a session dictionary from a file at the specified path and returns it.

    Args:
        path (str): The file path from which to load the session data.

    Returns:
        dict: The session data as a dictionary, or an empty dict if the file does not exist or is empty.
    """
    if not os.path.exists(path):
        return {}

    try:
        with open(path, 'r', encoding='utf-8') as file:
            data = file.read().strip()
            if data:
                return json.loads(data)
            else:
                return {}
    except (json.JSONDecodeError, ValueError):
        return {}
