import boto3
from botocore.exceptions import NoCredentialsError, ClientError

def get_s3_client():
    """
    Returns a boto3 S3 client configured for the us-east-1 region.
    The client is authenticated using AWS credentials (typically from environment variables or AWS config).
    This client can be used to list and download objects from private S3 buckets.
    """
    try:
        # Create S3 client for us-east-1 region
        s3_client = boto3.client(
            's3',
            region_name='us-east-1'
        )
        return s3_client
    except NoCredentialsError:
        raise Exception("AWS credentials not found. Please configure AWS credentials (e.g., via AWS CLI or environment variables).")
    except ClientError as e:
        if e.response['Error']['Code'] == 'InvalidAccessKeyId':
            raise Exception("Invalid AWS access key ID. Please verify your credentials.")
        elif e.response['Error']['Code'] == 'SignatureDoesNotMatch':
            raise Exception("Invalid AWS signature. Please check your credentials and network configuration.")
        else:
            raise Exception(f"Unexpected error when creating S3 client: {str(e)}")
