    // Check if exactly one argument is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <argument>\n", argv[0]);
        return 1;
    }

    // Create a local buffer to store the argument
    char buffer[256];  // Safe size for typical command-line arguments

    // Copy the argument into the buffer
    // Using strncpy to avoid buffer overflow (though argv[1] is guaranteed to be null-terminated)
    strncpy(buffer, argv[1], sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';  // Ensure null termination

    // Print the stored value
    printf("Stored: %s\n", buffer);

    return 0;
}
