void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    size_t level_len = strlen(level);
    size_t message_len = strlen(message);
    size_t total_len = level_len + 2 + message_len; // [LEVEL] message -> [ ] + level + ] + space + message

    if (total_len >= out_len) {
        out[0] = '\0';
        return;
    }

    // Copy the opening bracket and level
    out[0] = '[';
    memcpy(out + 1, level, level_len);

    // Null-terminate the level part
    out[1 + level_len] = ']';

    // Add a space after the level
    out[1 + level_len + 1] = ' ';

    // Copy the message
    memcpy(out + 2 + level_len + 2, message, message_len);

    // Null-terminate the entire string
    out[2 + level_len + 2 + message_len] = '\0';
}
