void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Validate input parameters to prevent buffer overflow and use-after-free
    if (out == NULL || out_len == 0 || level == NULL || message == NULL) {
        // If any parameter is invalid, write a minimal safe string
        if (out_len > 0) {
            out[0] = '\0';
        }
        return;
    }

    // Calculate the required buffer size for the formatted string
    // Format: [LEVEL] message\n (with null terminator)
    size_t level_len = strlen(level);
    size_t message_len = strlen(message);
    size_t total_len = 1 + level_len + 1 + message_len + 1; // [ ] + message + \0

    // Check if the output buffer is large enough
    if (total_len >= out_len) {
        // Buffer is too small, write as much as possible
        out[0] = '\0';
        return;
    }

    // Copy the formatted string safely
    char *dest = out;
    *dest = '[';
    dest++;

    // Copy level string
    size_t copied = strlcpy(dest, level, out_len - 1 - level_len);
    if (copied >= out_len - 1 - level_len) {
        // Buffer overflow would occur, truncate and ensure null termination
        dest[0] = '\0';
        return;
    }

    dest += copied;
    *dest = ']';
    dest++;

    // Copy message string
    copied = strlcpy(dest, message, out_len - (dest - out));
    if (copied >= out_len - (dest - out)) {
        // Buffer overflow would occur, truncate and ensure null termination
        dest[0] = '\0';
        return;
    }

    // Null terminate the result
    *dest = '\0';
}
