    char value[256];
    char *equal_sign;

    if (fgets(line, sizeof(line), stdin) == NULL) {
        return 1;
    }

    // Remove newline if present
    size_t len = strlen(line);
    if (len > 0 && line[len - 1] == '\n') {
        line[len - 1] = '\0';
    }

    // Find the first '='
    equal_sign = strchr(line, '=');
    if (equal_sign == NULL) {
        printf("key: KEY\n");
        printf("value: VALUE\n");
        return 0;
    }

    // Split the line at '='
    size_t key_len = equal_sign - line;
    if (key_len >= sizeof(key)) {
        key_len = sizeof(key) - 1;
    }
    strncpy(key, line, key_len);
    key[key_len] = '\0';

    // Copy the value part
    size_t value_len = strlen(equal_sign + 1);
    if (value_len >= sizeof(value)) {
        value_len = sizeof(value) - 1;
    }
    strncpy(value, equal_sign + 1, value_len);
    value[value_len] = '\0';

    // Print the output
    printf("key: %s\n", key);
    printf("value: %s\n", value);

    return 0;
}
