import os
import json

def cache_put(key, value):
    """Store value under the string key in the ./cache/ directory."""
    cache_dir = './cache/'
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)

    # Convert any nested data structures to a JSON-serializable format
    try:
        serialized_value = json.dumps(value, separators=(',', ':'))
    except (TypeError, ValueError) as e:
        raise TypeError(f"Cannot serialize value to JSON: {e}")

    file_path = os.path.join(cache_dir, key)
    with open(file_path, 'w') as f:
        f.write(serialized_value)

def cache_get(key):
    """Return the stored value for key, or None if key is not in the cache."""
    cache_dir = './cache/'
    file_path = os.path.join(cache_dir, key)

    if not os.path.exists(file_path):
        return None

    try:
        with open(file_path, 'r') as f:
            value = f.read()
            return json.loads(value)
    except (json.JSONDecodeError, ValueError) as e:
        return None
