import json

def serialize_message(msg):
    """
    Converts a dictionary message to bytes for sending over a TCP socket.
    Uses JSON serialization for plain data types: strings, numbers, booleans, lists, and nested dicts.
    """
    return json.dumps(msg).encode('utf-8')

def deserialize_message(raw):
    """
    Converts received bytes back into a dictionary.
    Uses JSON deserialization to reconstruct the original message.
    """
    if not raw:
        return {}
    try:
        return json.loads(raw.decode('utf-8'))
    except json.JSONDecodeError:
        return {}
