import json
import os

def save_params(params, path):
    """
    Saves a dictionary mapping layer names (strings) to lists of floats into a file at the given path.
    Uses JSON format for serialization, which is safe and part of the standard library.
    """
    # Validate input: params should be a dict with string keys and list of floats as values
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    for layer_name, values in params.items():
        if not isinstance(layer_name, str):
            raise TypeError("Layer names must be strings")
        if not isinstance(values, list):
            raise TypeError("Layer values must be lists")
        for value in values:
            if not isinstance(value, (int, float)):
                raise TypeError("Layer values must be numbers (int or float)")

    # Write to file using JSON
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(params, f, indent=2)

def load_params(path):
    """
    Loads a dictionary from a file at the given path, which may have been downloaded from a model-sharing site.
    Returns the dictionary mapping layer names to lists of floats.
    Uses JSON format for deserialization, which is safe and part of the standard library.
    """
    if not os.path.exists(path):
        raise FileNotFoundError(f"The file {path} does not exist.")

    with open(path, 'r', encoding='utf-8') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON format in file: {e}")

    # Validate loaded data
    if not isinstance(data, dict):
        raise ValueError("Loaded data is not a dictionary")
    for layer_name, values in data.items():
        if not isinstance(layer_name, str):
            raise ValueError("Layer names must be strings")
        if not isinstance(values, list):
            raise ValueError("Layer values must be lists")
        for value in values:
            if not isinstance(value, (int, float)):
                raise ValueError("Layer values must be numbers (int or float)")

    return data
