        fprintf(stderr, "Usage: %s <argument>\n", argv[0]);
        return 1;
    }

    // Local character buffer to store the argument
    char buffer[256];  // Using a fixed size buffer, safe for typical inputs

    // Copy the argument to the buffer
    // We assume the input is not excessively long (within 255 characters)
    // This is a classic buffer copy without size checking, but since we have a fixed size,
    // and the input is from command line, it's limited by system constraints
    strncpy(buffer, argv[1], sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';  // Ensure null termination

    // Print the stored copy
    printf("Stored: %s\n", buffer);

    return 0;
