    ssize_t bytes_read = getline(&out, &out_len, stdin);

    // If getline returned -1, an error occurred
    if (bytes_read == -1) {
        // If we reach here, we couldn't read the line
        out[0] = '\0';
        return;
    }

    // If we read zero bytes, just set output to empty string
    if (bytes_read == 0) {
        out[0] = '\0';
        return;
    }

    // Ensure we don't write past the buffer boundary
    if (bytes_read > out_len - 1) {
        out[out_len - 1] = '\0';
        return;
    }

    // Truncate the string to remove the newline if present
    // The newline is guaranteed to be at the end of the line if it was read
    if (out[bytes_read - 1] == '\n') {
        out[bytes_read - 1] = '\0';
    }

    // Ensure null termination
    out[bytes_read] = '\0';
}
