    while (bytes_read < out_len - 1) {
        int ch = getchar();
        if (ch == EOF) {
            break;
        }
        if (ch == '\n') {
            // Found newline, stop reading and remove it
            buf[bytes_read] = '\0';
            break;
        }
        buf[bytes_read] = (char)ch;
        bytes_read++;
        if (bytes_read >= out_len - 1) {
            // Buffer overflow protection: leave space for null terminator
            buf[bytes_read] = '\0';
            break;
        }
    }

    // Ensure null termination
    if (bytes_read >= out_len - 1) {
        out[out_len - 1] = '\0';
    }
}
