    except ClientError as e:
        if e.response['Error']['Code'] == 'InvalidAccessKeyId':
            raise RuntimeError("Invalid AWS access key ID. Please verify your credentials.")
        elif e.response['Error']['Code'] == 'SignatureDoesNotMatch':
            raise RuntimeError("Invalid AWS signature. Please verify your credentials and network configuration.")
        else:
            raise RuntimeError(f"Failed to create S3 client: {e}")
