void read_username(char *out, size_t out_len) {
    if (out == NULL || out_len == 0) {
        return;
    }

    ssize_t bytes_read = 0;
    char *buf = out;
    size_t remaining = out_len;

    // Read one line from stdin, stopping at newline or EOF
    while (bytes_read < out_len - 1) {
        ssize_t ch = getchar();
        if (ch == EOF) {
            break;
        }
        if (ch == '\n') {
            // Found newline, so we stop and remove it
            *buf = '\0';
            return;
        }
        *buf = (char)ch;
        buf++;
        bytes_read++;
    }

    // If we reached here, we've read all the characters without a newline
    // So we ensure the buffer is null-terminated
    *buf = '\0';
}
