        return;
    }

    ssize_t bytes_read = read(STDIN_FILENO, out, out_len - 1);
    if (bytes_read <= 0) {
        out[0] = '\0';
        return;
    }

    // Null-terminate the string (leaving space for newline)
    out[bytes_read] = '\0';

    // Remove trailing newline if present
    char *ptr = out + bytes_read - 1;
    while (ptr >= out && *ptr == '\n') {
        *ptr = '\0';
        ptr--;
    }
}
