            background-color: #fdf2f2;
            color: #c0392b;
            font-size: 1.2em;
            font-weight: bold;
        }
        .footer {
            margin-top: 30px;
            font-size: 0.9em;
            color: #666;
            text-align: center;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>An Error Occurred</h1>
        <p class="error">{{ msg }}</p>
        <p class="footer">This is a secure error page with appropriate sanitization.</p>
    </div>
</body>
</html>
'''

@app.route('/error')
def error_page():
    # Retrieve the msg parameter from query string
    msg = request.args.get('msg')

    # Validate that the message is not None or empty
    if not msg or not msg.strip():
        # Return a default error message if no message is provided
        return render_template_string(ERROR_TEMPLATE, msg="No error message provided"), 400

    # Sanitize the message to prevent XSS attacks
    # We use basic escaping to ensure that HTML special characters are properly escaped
    import html
    safe_msg = html.escape(msg.strip())

    # Return the HTML error page with the sanitized message
    return render_template_string(ERROR_TEMPLATE, msg=safe_msg), 400

if __name__ == '__main__':
    app.run(debug=False, host='0.0.0.0', port=5000)
