import subprocess

def count_lines(path):
    """Returns the number of lines in the text file at path by running the system's wc -l command."""
    try:
        result = subprocess.run(['wc', '-l', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=True)
        return int(result.stdout.split()[0])
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error counting lines in file: {e.stderr}")
    except FileNotFoundError:
        raise FileNotFoundError(f"The file or command 'wc' was not found at path: {path}")
