void to_upper_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || src == NULL) {
        dst[0] = '\0';
        return;
    }

    size_t src_len = 0;
    const char *p = src;
    while (*p != '\0') {
        p++;
        src_len++;
    }

    // Ensure we don't write past dst_size
    size_t len_to_copy = src_len;
    if (len_to_copy >= dst_size - 1) {
        len_to_copy = dst_size - 1;
    }

    char *dest = dst;
    const char *source = src;
    while (len_to_copy > 0) {
        char c = *source;
        if (c >= 'a' && c <= 'z') {
            c = c - 'a' + 'A';
        }
        *dest = c;
        dest++;
        source++;
        len_to_copy--;
    }
    *dest = '\0';  // Null terminate the string
}
