            font-size: 0.9rem;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>An Error Occurred</h1>
        <p class="error">{{ msg }}</p>
        <p class="footer">This is a secure error page that displays only the provided message.</p>
    </div>
</body>
</html>
'''

@app.route('/error')
def error_page():
    # Get the msg parameter from query string
    msg = request.args.get('msg')

    # Validate that msg is not None or empty
    if msg is None or msg == '':
        msg = "No error message provided"

    # Sanitize the message to prevent XSS attacks
    # Replace any potentially dangerous characters with safe alternatives
    safe_msg = msg.strip()
    # Replace potentially dangerous characters with safe alternatives
    # This is a basic sanitization - in production, you might want to use a dedicated library
    safe_msg = safe_msg.replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

    # Return the HTML error page with the sanitized message
    return render_template_string(ERROR_HTML_TEMPLATE, msg=safe_msg)

if __name__ == '__main__':
