        try:
            data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON format in file {path}: {str(e)}")

    # Validate that data is a dictionary and all values are lists of floats
    if not isinstance(data, dict):
        raise ValueError(f"Expected a dictionary, but got {type(data).__name__}")

    for layer_name, values in data.items():
