    size_t message_len = strlen(message);
    size_t total_len = level_len + 2 + message_len; // for "[LEVEL] message" including the space and the closing bracket
    size_t max_needed = total_len + 1; // +1 for null terminator

    // Check if buffer is large enough to hold the formatted string
    if (out_len < max_needed) {
        // If buffer is too small, we cannot safely write without overflow
        // This is a minimal defense against out-of-bounds write
        out[0] = '\0';
        return;
    }

    // Format the string: [LEVEL] message
    out[0] = '[';
    memcpy(out + 1, level, level_len);
    out[1 + level_len] = ']';
    out[1 + level_len + 1] = ' ';
    memcpy(out + 2 + level_len + 1, message, message_len);
    out[2 + level_len + 1 + message_len] = '\0';
