void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the required size for the log entry: [LEVEL] message + 1 for null terminator
    size_t level_len = strlen(level);
    size_t msg_len = strlen(message);
    size_t total_len = level_len + 1 + msg_len + 1; // +1 for space between level and message, +1 for null terminator

    // Check if the total length exceeds the output buffer size
    if (total_len >= out_len) {
        // Buffer is too small; write as much as possible
        size_t available = out_len - 1; // -1 for null terminator
        if (available > 0) {
            // Write the level part
            size_t written = snprintf(out, available, "[%.*s] ", (int)level_len, level);
            if (written >= available) {
                out[available - 1] = '\0'; // Truncate and null-terminate
            }
            // Write the message part, if space remains
            size_t remaining = available - written - 1;
            if (remaining > 0) {
                size_t msg_written = snprintf(out + written, remaining, "%.*s", (int)msg_len, message);
                if (msg_written >= remaining) {
                    out[written + msg_written - 1] = '\0';
                }
            }
        }
    } else {
        // Buffer is large enough; write the full log entry
        size_t written = snprintf(out, out_len, "[%s] %s", level, message);
        if (written >= out_len) {
            out[out_len - 1] = '\0';
        }
    }
}
